mapper.select:
SELECT ep_id, exam_id, student_id, join_status, join_time, submit_time
FROM exam_participant
WHERE exam_id = #{examId} AND student_id = #{studentId}

mapper.update:
UPDATE exam_participant
SET join_status = #{joinStatus}
WHERE exam_id = #{examId} AND student_id = #{studentId}

UPDATE exam_participant
